import fs from 'fs';
import { Command } from 'commander';
import ora from 'ora';
import { git } from '../utils/git.js';
import { resolveConflict } from '../ai/conflictResolver.js';

export function registerResolve(program: Command) {
  program
    .command('resolve')
    .description('Resolve merge conflicts with AI assistance')
    .option('--ai', 'Use AI to suggest resolution')
    .action(async opts => {
      const gitClient = git();
      const status = await gitClient.status();
      if (status.conflicted.length === 0) {
        console.log('No conflicts detected.');
        return;
      }
      if (!opts.ai) {
        console.log('Conflicted files:', status.conflicted.join(', '));
        return;
      }
      for (const file of status.conflicted) {
        const spinner = ora(`Resolving ${file}...`).start();
        const content = fs.readFileSync(file, 'utf8');
        const merged = await resolveConflict(file, content);
        fs.writeFileSync(file, merged);
        spinner.succeed(`Applied AI suggestion for ${file}`);
      }
    });
}
